systemQueries:
# id: threats_to_validity_types # Purpose: list the threat-to-validity node of each template instance, with the types of threat (predicates) it reports SELECT DISTINCT ?contribution ?paper ?paperLabel ?venue_name ?threat ?threat_label ?threat_type ?threat_type_label WHERE {
  # Declare the contribution as an instance of the template class (the paper link was not discovered) ?contribution a orkgc:C27001 .
  # Venue of the contribution ?contribution orkgp:P135046 ?venue .
  # Human-readable venue label ?venue rdfs:label ?venue_name .
  # Restrict to the IEEE International Requirements Engineering Conference (case-insensitive) FILTER(LCASE(STR(?venue_name)) = LCASE("IEEE International Requirements Engineering Conference")) # Threat-to-validity node reported in the publication ?contribution orkgp:P39099 ?threat .
  # Optional label of the threat node OPTIONAL {
    ?threat rdfs:label ?threat_label .
  } # Each outgoing predicate of the threat node is a reported threat type (e.g. external, internal, construct, conclusion) OPTIONAL {
    # Outgoing predicate from the threat node ?threat ?threat_type ?threat_value .
    # Label of the predicate, which names the threat type ?threat_type rdfs:label ?threat_type_label .
  } # Optionally attach the paper if it is linked directly via P31 OPTIONAL {
    # Paper that has this contribution ?paper orkgp:P31 ?contribution .
    # Paper title ?paper rdfs:label ?paperLabel .
  }
} # Order by paper title for stable output ORDER BY ?paperLabel

# id: threats_to_validity_values # Purpose: list the values (e.g. external, internal, construct, conclusion threat descriptions) stored under each threat node SELECT DISTINCT ?contribution ?paper ?paperLabel ?threat_type_label ?threat_value ?threat_value_label WHERE {
  # Declare the contribution as an instance of the template class ?contribution a orkgc:C27001 .
  # Venue of the contribution ?contribution orkgp:P135046 ?venue .
  # Venue label ?venue rdfs:label ?venue_name .
  # Restrict to the IEEE International Requirements Engineering Conference (case-insensitive) FILTER(LCASE(STR(?venue_name)) = LCASE("IEEE International Requirements Engineering Conference")) # Threat-to-validity node ?contribution orkgp:P39099 ?threat .
  # Properties of the threat node and their values ?threat ?threat_type ?threat_value .
  # Label of the property, which names the threat type ?threat_type rdfs:label ?threat_type_label .
  # Optional label of the value if it is a resource OPTIONAL {
    ?threat_value rdfs:label ?threat_value_label .
  } # Optionally attach the paper if it is linked directly via P31 OPTIONAL {
    # Paper that has this contribution ?paper orkgp:P31 ?contribution .
    # Paper title ?paper rdfs:label ?paperLabel .
  }
} # Order by paper title and threat type ORDER BY ?paperLabel ?threat_type_label

