# id: methods_per_paper_over_time # Declare the ORKG prefixes # Average number of distinct research methods per publication, grouped by publication year SELECT ?year (COUNT(?paper) AS ?paperCount) (AVG(xsd:decimal(?methodCount)) AS ?avgMethodsPerPaper) WHERE {
  # Inner query: count distinct methods for each paper and its publication year {
    SELECT ?paper ?year (COUNT(DISTINCT ?methodLabel) AS ?methodCount) WHERE {
      # Link the paper to its contribution ?paper orkgp:P31 ?contribution .
      # Restrict to contributions of the Empirical Research Practice template ?contribution a orkgc:C27001 .
      # Get the publication year from the paper (not the contribution) ?paper orkgp:P29 ?year .
      # Collect methods either from the data collection branch or the data analysis branch {
        # Data collection methods: contribution -> data collection -> method ?contribution orkgp:P56008 ?dataCollection .
        ?dataCollection orkgp:P1005 ?method .
      }
UNION {
        # Data analysis methods: contribution -> data analysis -> method ?contribution orkgp:P15124 ?dataAnalysis .
        ?dataAnalysis orkgp:P1005 ?method .
      } # Get the human-readable label of each method ?method rdfs:label ?methodLabel .
    } # Count distinct methods per paper and year GROUP BY ?paper ?year
  }
} # Aggregate per year to show how methods per publication evolve over time GROUP BY ?year # Order chronologically ORDER BY ?year

